-- Backfill (run once, after sql/2026-10-29-signing-waves.sql). Idempotent: INSERT OR IGNORE, and
-- only rows without a wave are set. Harry, 29.10.2026: waves are the PDF date, as in the РИК; every
-- date so far was sent; on 29.10 only the people already downloaded for signing (the real signing
-- run that day) are closed, anyone numbered 29.10 and not downloaded stays in the open 29.10 wave.
-- Withdrawn and duplicate rows get the wave too (they are left out of the ZIP and tables anyway).

INSERT OR IGNORE INTO signing_waves (id, issue_date, closed_at, closed_by) VALUES ('backfill-2026-10-19', '2026-10-19', '2026-10-19T20:59:00.000Z', 'backfill');
UPDATE signups SET designation_wave_id = 'backfill-2026-10-19' WHERE designation_wave_id IS NULL AND designation_number IS NOT NULL AND (CASE WHEN designation_issued_at LIKE '__.__.____' THEN substr(designation_issued_at, 7, 4) || '-' || substr(designation_issued_at, 4, 2) || '-' || substr(designation_issued_at, 1, 2) WHEN designation_issued_at LIKE '____-__-__%' THEN substr(designation_issued_at, 1, 10) ELSE '' END) = '2026-10-19';
UPDATE partner_people SET designation_wave_id = 'backfill-2026-10-19' WHERE designation_wave_id IS NULL AND designation_number IS NOT NULL AND (CASE WHEN designation_issued_at LIKE '__.__.____' THEN substr(designation_issued_at, 7, 4) || '-' || substr(designation_issued_at, 4, 2) || '-' || substr(designation_issued_at, 1, 2) WHEN designation_issued_at LIKE '____-__-__%' THEN substr(designation_issued_at, 1, 10) ELSE '' END) = '2026-10-19';
